import { mountAlarmWheels } from './alarm-wheels.js';
import { createAuraRenderer, AURA_STATES } from './aura-renderer.js';
import { icon } from './icons.js';
import { LIGHT_COLORS, supportsColor, colorPayload, serviceRequest, TEMPERATURE_SENSORS, temperatureCelsius } from './device-contracts.js';

const root=document.getElementById('ambient-assistant');
const q=s=>root.querySelector(s);
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const colors=Object.fromEntries(Object.entries(LIGHT_COLORS).map(([name,c])=>[name,c.hex]));
const localDateTime=ms=>{const d=new Date(ms);return new Date(ms-d.getTimezoneOffset()*60000).toISOString().slice(0,16);};
const clockTime=ms=>new Date(ms).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'});
const duration=seconds=>{const t=Math.max(0,Math.ceil(seconds)),h=Math.floor(t/3600);return (h?h+':':'')+String(Math.floor(t/60)%60).padStart(2,'0')+':'+String(t%60).padStart(2,'0');};
function nextAlarm(time,now){const [h,m]=time.split(':').map(Number);const d=new Date(now);d.setHours(h,m,0,0);if(d.getTime()<=now)d.setDate(d.getDate()+1);return d.getTime();}
function until(ms){const m=Math.max(0,Math.ceil((ms-Date.now())/60000));return Math.floor(m/60)+'h '+m%60+'m';}
function setText(selector,text){const n=q(selector);if(n&&n.textContent!==text)n.textContent=text;}
const model={view:'home',agent:'idle',muted:false,remindersExpanded:false,remindersEditUntil:0,alarmPickerOpen:false,reminderMenuOpen:false,reminderAccordionOpen:true,soundMuted:false,pendingReminder:null,history:[],historyIndex:0,lastInteraction:Date.now(),event:null,receiptAt:0,selectedLight:0,
  lights:[{id:'light.living_room',name:'Living room',room:'Ceiling',on:true,brightness:65,color:'Warm white'},{id:'light.reading_lamp',name:'Reading lamp',room:'Living room',on:true,brightness:35,color:'Warm white'},{id:'light.kitchen',name:'Kitchen',room:'Pendant',on:false,brightness:80,color:'Cool white'},{id:'light.bedroom',name:'Bedroom',room:'Bedside',on:false,brightness:25,color:'Red'}],
  target:24,current:26,temperatureSensor:'sensor.living_room_temperature',timer:null,alarm:null,timerDraft:300,alarmDraft:'07:00',reminderDraft:'',reminderDeadline:'',editingReminder:null,
  reminders:[{id:1,text:'Water the plants',deadline:null,done:false,unread:true,nearShown:false,dueShown:false},{id:2,text:'Pick up oat milk',deadline:null,done:false,unread:false,nearShown:false,dueShown:false}],
  auto:null,toast:null,alert:null,alertQueue:[],call:null,cameraExpanded:false,cameraEnabled:true,playing:false,mediaLoaded:false,position:0,shuffle:false,repeat:'off',song:0,volume:40,request:0,returnFocus:null};
const tracks=[['Weightless','Marconi Union',509],['A Walk','Tycho',316],['First Breath','Helios',432]];
for(const l of model.lights){l.supported_color_modes=l.id==='light.kitchen'?['color_temp']:['rgb','color_temp'];l.min_color_temp_kelvin=2200;l.max_color_temp_kelvin=6500;l.lastBrightness=l.brightness;}
const aura=createAuraRenderer(q('.livekit-aura'),{onFailure:message=>{q('.aura-fallback').hidden=false;q('.livekit-aura').hidden=true;root.dataset.auraError=message;}});
root.dataset.view='home';root.dataset.state='idle';
let stateReturn=null,speechInterval=null,dialPointer=null,lastRail='',lastReminderWidgets='';
let reminderOrderDrag=null,alarmWheels=null;
for(const r of model.reminders){r.pinned=false;r.visibleUntil=0;}
function setAgent(state,{settle=false}={}){
  if(!(state in AURA_STATES))throw new Error('Unknown state');
  model.agent=state;root.dataset.state=state;root.dataset.muted=String(model.muted);const mic=q('.mute-indicator');mic.innerHTML=icon(model.muted?'mic-off':'mic');mic.setAttribute('aria-label',model.muted?'Unmute microphone':'Mute microphone');mic.setAttribute('aria-pressed',String(model.muted));q('.wake-target').setAttribute('aria-pressed',String(state==='listening'));q('.wake-target').setAttribute('aria-label',model.muted?'Assistant muted':state==='listening'?'Stop listening':'Wake assistant');aura.update({state,muted:model.muted,volume:0});
  setText('[data-agent-label]',model.muted?'Muted':['idle','disconnected'].includes(state)?'':state==='failed'?'Try again':state.replaceAll('-',' '));
  clearInterval(speechInterval);speechInterval=null;
  if(state==='speaking'&&!model.muted){speechInterval=setInterval(()=>{if(document.hidden)return;const t=performance.now()/1000;const syllable=Math.pow(Math.max(0,Math.sin(t*5.4)+.43*Math.sin(t*13.1)),1.1);aura.update({volume:Math.min(.95,.14+syllable*.58)});},80);}
  clearTimeout(stateReturn);if(settle)stateReturn=setTimeout(()=>setAgent('idle'),1900);
}
function receipt(intent,parameters={},source='touch'){
 const timestamp=Date.now();const request=serviceRequest(intent,parameters);
 model.event={type:source==='onnx-simulated'?'inference':'interaction',simulated:true,source,timestamp:new Date(timestamp).toISOString(),result:{utteranceId:crypto.randomUUID(),revision:0,final:true,intent,parameters,...(source==='onnx-simulated'?{confidence:1,latencyMs:380}:{})},...(request?{request}:{})};
 model.history.unshift(model.event);model.history=model.history.slice(0,30);model.historyIndex=0;model.receiptAt=timestamp;q('.intent-receipt').hidden=false;q('.intent-receipt').classList.remove('quiet');setText('[data-intent]',intent);setText('[data-parameters]',Object.entries(parameters).map(([k,v])=>k+'='+JSON.stringify(v)).join(' · ')||'{}');
}
function autoStart(action){model.auto={action,remaining:5000,last:performance.now(),paused:false};updateAuto();}
function stopAuto(){if(!model.auto)return;model.auto=null;const stroke=q('.count-stroke');if(stroke)stroke.toggleAttribute('hidden',true);setText('[data-auto-caption]','Save when ready');}
function updateAuto(){if(!model.auto)return;const stroke=q('.count-stroke');if(stroke)stroke.toggleAttribute('hidden',false);const pct=1-model.auto.remaining/5000;q('.task-content').style.setProperty('--count-offset',String(pct*100));setText('[data-auto-caption]',`${model.auto.action==='reminder'?'“Reminder”':model.auto.action==='timer'?duration(model.timerDraft):clockTime(nextAlarm(model.alarmDraft,Date.now()))} in ${Math.ceil(model.auto.remaining/1000)}s`);}
function autoButton(label,action){return `<button type="button" class="button-primary auto-action" data-action="${action}"><svg hidden class="count-stroke" viewBox="0 0 220 62" preserveAspectRatio="none" aria-hidden="true"><rect x="1" y="1" width="218" height="60" rx="30" pathLength="100"></rect></svg>${label}</button>`;}
function toast(symbol,title,detail,target,undo=null){model.toast={symbol,title,detail,target,undo,until:Date.now()+4200,remaining:4200,held:false};q('.toast').hidden=false;q('.toast').classList.remove('fading');q('.toast').style.setProperty('--toast-progress','1');q('.toast-main').innerHTML=icon(symbol)+`<span><strong>${esc(title)}</strong><small>${esc(detail)}</small></span>`;if(symbol==='lightbulb'&&target==='lights'){const l=model.lights[model.selectedLight],glyph=q('.toast-main>svg');glyph.style.color=l.on?colors[l.color]:'#7f929a';glyph.style.filter=l.on?`drop-shadow(0 0 ${l.brightness/7}px ${colors[l.color]})`:'none';}setText('[data-announcement]',title+'. '+detail);}
function closeToast(){model.toast=null;q('.toast').hidden=true;}
function reminderEntry(r,i,home=false){return `<div class="reminder-widget ${r.pinned?'is-pinned':''}  " data-widget-id="${r.id}" data-reminder-swipe="${i}"><button class="reminder-done-action" data-complete-reminder="${i}" aria-label="Mark ${esc(r.text)} as done">Mark as done ${icon('chevron-right')}</button><div class="reminder-front"><button class="reminder-grip" data-reorder-reminder="${i}" data-reminder-id="${r.id}" aria-label="Reorder ${esc(r.text)}; use up and down arrows">${icon('grip-vertical')}</button><button class="reminder-copy" data-reminder="${i}"><strong>${esc(r.text)}</strong>${r.deadline?`<small>${clockTime(r.deadline)}</small>`:''}</button>${r.unread?'<i class="unread" aria-label="New reminder"></i>':''}<button class="pin-reminder" data-pin-reminder="${i}" aria-label="${r.pinned?'Unpin':'Pin'} ${esc(r.text)}" aria-pressed="${!!r.pinned}">${icon('pin')}</button></div></div>`;}
function refreshReminderSurfaces(){renderReminderCount();if(model.view==='control'){const menu=q('.cc-reminder-menu');if(menu)menu.outerHTML=renderReminderMenu();}else if(model.view==='reminders')renderView();}
function completeReminder(index){const r=model.reminders[index];r.done=true;r.unread=false;model.pendingReminder=null;receipt('reminder.complete',{id:r.id,done:true});refreshReminderSurfaces();}
function accordionHeader(count,expanded,action){return `<button class="reminder-accordion-toggle" data-action="${action}" aria-expanded="${expanded}"><strong>${count}</strong><span>Reminders</span>${icon(expanded?'chevron-up':'chevron-down')}</button>`;}
function homeReminder(r,i,position,editing){if(editing)return reminderEntry(r,i,true);return `<div class="reminder-widget quiet-row" data-widget-id="${r.id}" data-reminder-swipe="${i}"><button class="reminder-done-action" data-complete-reminder="${i}" aria-label="Mark ${esc(r.text)} as done">Mark as done ${icon('chevron-right')}</button><div class="reminder-front"><button class="quiet-reminder" data-reminder="${i}" aria-label="${esc(r.text)}${r.deadline?', '+clockTime(r.deadline):''}"><span><strong>${esc(r.text)}</strong>${r.deadline?`<small>${clockTime(r.deadline)}</small>`:''}</span><span class="reminder-number" aria-hidden="true">${position+1}</span></button></div></div>`;}
function renderReminderCount(){
 const now=Date.now(),remaining=model.reminders.filter(r=>!r.done);setText('[data-reminder-count]',String(remaining.length));q('[data-unread-dot]').hidden=!remaining.some(r=>r.unread);
 if(model.remindersExpanded&&now>=model.remindersEditUntil&&!reminderOrderDrag&&!reminderDrag){model.remindersExpanded=false;model.pendingReminder=null;}
 const editing=model.remindersExpanded;root.dataset.reminderEditing=String(editing);q('.reminder-trigger').setAttribute('aria-expanded',String(editing));q('.reminder-trigger').setAttribute('aria-label',`${editing?'Close':'Open'} ${remaining.length} reminders`);
 if(reminderOrderDrag)return;
 const shown=model.reminders.map((r,i)=>({r,i})).filter(({r})=>!r.done&&(editing||r.pinned));
 const widgets=shown.map(({r,i},position)=>homeReminder(r,i,position,editing)).join('');
 if(widgets!==lastReminderWidgets){q('.home-reminders').innerHTML=widgets;lastReminderWidgets=widgets;}
}
function revealReminders(){model.remindersExpanded=!model.remindersExpanded;model.remindersEditUntil=model.remindersExpanded?Date.now()+30000:0;model.pendingReminder=null;renderReminderCount();}
function renderReminderMenu(){return `<div class="cc-reminder-menu"><section class="reminder-accordion">${accordionHeader(model.reminders.filter(r=>!r.done).length,model.reminderAccordionOpen,'reminder-accordion')}<div class="reminder-accordion-body" ${model.reminderAccordionOpen?'':'hidden'}>${model.reminders.map((r,i)=>r.done?'':reminderEntry(r,i)).join('')||'<p class="empty-reminders">All done</p>'}</div></section></div>`;}
function analogClock(time,className=''){const [h,m]=time.split(':').map(Number);return `<span class="analog-clock ${className}" role="img" aria-label="${esc(time)}" style="--hour-angle:${h%12*30+m*.5}deg;--minute-angle:${m*6}deg"><i class="hour-hand"></i><i class="minute-hand"></i><i class="clock-pivot"></i></span>`;}
function paintControlStatus(){if(model.view!=='control')return;setText('[data-cc-timer]',model.timer?duration(timerRemaining()):'Timer');q('.cc-timer-hourglass')?.classList.toggle('paused',!model.timer?.end);setText('[data-cc-alarm]',model.alarm?'In '+until(model.alarm.deadline):'Alarm');if(model.alarmPickerOpen)paintAlarmPreview();}
function paintAlarmPreview(){setText('[data-alarm-until]','In '+until(nextAlarm(model.alarmDraft,Date.now())));const clock=q('.alarm-preview .analog-clock');if(clock){const [h,m]=model.alarmDraft.split(':').map(Number);clock.style.setProperty('--hour-angle',(h%12*30+m*.5)+'deg');clock.style.setProperty('--minute-angle',m*6+'deg');clock.setAttribute('aria-label',model.alarmDraft);}}
function renderControl(){
 const activeLights=model.lights.map((l,i)=>({l,i})).filter(({l})=>l.on);
 const primary=model.alarmPickerOpen?`<div class="inline-alarm"><div class="alarm-preview">${analogClock(model.alarmDraft)}<span data-alarm-until>In ${until(nextAlarm(model.alarmDraft,Date.now()))}</span></div><div class="alarm-wheels" aria-label="Alarm time"></div><div class="alarm-wheel-actions"><button data-action="alarm-picker-close" aria-label="Cancel alarm setting">${icon('x')}</button>${model.alarm?`<button data-action="alarm-remove" aria-label="Remove alarm">${icon('trash-2')}</button>`:''}<button class="alarm-confirm" data-action="alarm-save" aria-label="Set alarm">${icon('check')}</button></div></div>`:
 `<div class="cc-media"><button data-open="music" class="cc-track">${icon('disc-3')}<span><strong>${model.mediaLoaded?tracks[model.song][0]:'Music'}</strong><small>${model.mediaLoaded?tracks[model.song][1]:'Choose a track'}</small></span></button><button data-action="playpause" aria-label="${model.playing?'Pause':'Play'} music">${icon(model.playing?'pause':'play')}</button></div><div class="cc-grid"><button data-open="lights">${icon('lightbulb')}<span>Lights</span></button><button data-open="climate">${icon('thermometer')}<span>${model.target}°</span><small>${model.current===null?'Unavailable':model.current+'° inside'}</small></button><button data-open="timer"><span class="cc-timer-hourglass ${model.timer?.end?'':'paused'}">${icon('hourglass')}</span><span data-cc-timer>${model.timer?duration(timerRemaining()):'Timer'}</span></button><button data-open="alarm">${model.alarm?analogClock(model.alarm.time):icon('alarm-clock')}<span data-cc-alarm>${model.alarm?'In '+until(model.alarm.deadline):'Alarm'}</span></button></div>${activeLights.length?`<div class="cc-light-grid" aria-label="Lights currently on">${activeLights.map(({l,i})=>`<div class="cc-light-tile" data-light-row="${i}"><button class="light-icon" data-light-toggle="${i}" aria-label="Turn off ${esc(l.name)}" aria-pressed="true">${icon('lightbulb')}</button><button class="light-name" data-quick-light="${i}" aria-label="Edit ${esc(l.name)}">${esc(l.name)}</button><span class="brightness-fill" aria-hidden="true"></span></div>`).join('')}</div>`:''}<div class="cc-volume"><button data-action="sound-mute" aria-label="Mute sounds">${icon('volume-2')}</button><input type="range" min="0" max="100" value="${model.volume}" data-input="volume" aria-label="Volume"></div>`;
 return `<div class="cc-columns"><div class="cc-secondary">${renderReminderMenu()}<div class="cc-reminder-actions"><button class="cc-square" data-open="reminders" aria-label="Open reminders">${icon('list-checks')}</button><button class="cc-square" data-action="new-reminder" aria-label="Add reminder">${icon('plus')}</button></div></div><div class="control-panel">${primary}<div class="cc-bottom"><button data-open="contacts" aria-label="Calls">${icon('phone')}</button><button data-open="demo" aria-label="Intent and aura simulator">${icon('sliders-horizontal')}</button></div></div></div>`;
}
function paintVolume(){root.dataset.soundMuted=String(model.soundMuted);for(const b of root.querySelectorAll('[data-action="sound-mute"]')){b.innerHTML=icon(model.soundMuted?'volume-x':'volume-2');b.setAttribute('aria-label',model.soundMuted?'Unmute sounds':'Mute sounds');b.setAttribute('aria-pressed',String(model.soundMuted));}for(const input of root.querySelectorAll('[data-input="volume"]')){input.style.setProperty('--volume-fill',model.volume+'%');input.setAttribute('aria-valuetext',model.soundMuted?model.volume+' percent, muted':model.volume+' percent');}}
function paintClock(){const value=new Date().toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit',hour12:false});const el=q('[data-clock]');if(el.dataset.time===value)return;el.dataset.time=value;el.setAttribute('aria-label',value);const [hour,minute]=value.split(':');el.innerHTML=`<span>${hour}</span><span class="clock-colon" aria-hidden="true"><i></i><i></i></span><span>${minute}</span>`;}
function restoreHome(){alarmWheels?.destroy();alarmWheels=null;model.alarmPickerOpen=false;model.view='home';root.dataset.view='home';q('.control-trigger').setAttribute('aria-expanded','false');q('.task-view').hidden=true;q('.screen-countdown').toggleAttribute('hidden',true);q('.home-layer').inert=false;q('.toast').inert=false;stopAuto();if(model.returnFocus?.isConnected)model.returnFocus.focus({preventScroll:true});model.lastInteraction=Date.now();renderRail();}
function open(view,{automatic=false}={}){
  model.alarmPickerOpen=view==='alarm';if(model.alarmPickerOpen){if(model.alarm&&/^\d\d:\d\d$/.test(model.alarm.time))model.alarmDraft=model.alarm.time;view='control';}
  if(model.view==='home')model.returnFocus=document.activeElement;
  stopAuto();if(view!=='control')closeToast();q('.toast').inert=view==='control';model.lastInteraction=Date.now();model.view=view;root.dataset.view=view;q('.control-trigger').setAttribute('aria-expanded',String(view==='control'));q('.task-view').hidden=false;q('.home-layer').inert=true;
  q('.back-button').hidden=!['new-reminder','call'].includes(view);q('.task-view').setAttribute('aria-label',view.replace('-',' '));
  if(view==='timer'&&!model.timer)model.timerDraft=300;
  if(view==='new-reminder'&&model.editingReminder===null){model.reminderDraft='';model.reminderDeadline='';}
  renderView();q('.close-task').focus({preventScroll:true});
  if(automatic)autoStart(view==='new-reminder'?'reminder':view);
}
function title(text){setText('[data-view-title]',text);}
function renderView(){alarmWheels?.destroy();alarmWheels=null;const pane=q('.task-content');pane.scrollTop=0;
 switch(model.view){
  case 'control':title('');pane.innerHTML=renderControl();paintVolume();model.lights.forEach((_,i)=>paintLight(i));if(model.alarmPickerOpen)alarmWheels=mountAlarmWheels(q('.alarm-wheels'),{value:model.alarmDraft,isMuted:()=>model.soundMuted,onChange:value=>{model.alarmDraft=value;model.lastInteraction=Date.now();paintAlarmPreview();}});break;
  case 'lights':{
    title('Lights');const light=model.lights[model.selectedLight];pane.innerHTML=`<div class="lights-layout"><div class="light-list" aria-label="Light list"><p class="gesture-hint">Swipe to dim</p>${model.lights.map((l,i)=>`<div class="light-row ${i===model.selectedLight?'selected':''}" data-light-row="${i}"><button class="light-icon" data-light-toggle="${i}" aria-label="Toggle ${esc(l.name)}" aria-pressed="${l.on}">${icon('lightbulb')}</button><button class="light-name" data-light-select="${i}" aria-label="Edit ${esc(l.name)}; double tap to toggle"><strong>${esc(l.name)}</strong><small><b data-row-brightness>${l.on?l.brightness+'%':'Off'}</b> · ${esc(l.room)}</small></button><span class="brightness-fill" aria-hidden="true"></span></div>`).join('')}<button class="subtle" data-action="all-off">All off</button></div><div class="light-editor"><div class="light-editor-head"><h2>${esc(light.name)}</h2><button class="switch" data-action="light-toggle" aria-label="Toggle ${esc(light.name)}" aria-pressed="${light.on}"><span><i></i></span></button></div><div class="light-preview">${icon('lightbulb')}<span class="subtle">${light.on?light.color:'Off'}</span></div><div class="label-line"><label for="brightness-v2">Brightness</label><strong data-brightness>${light.brightness}%</strong></div><input id="brightness-v2" data-input="brightness" aria-label="Brightness" type="range" min="0" max="100" value="${light.brightness}"><div class="label-line"><span>Color</span><span>${light.color}</span></div><div class="color-choices">${Object.entries(colors).filter(([name])=>supportsColor(light,name)).map(([name,color])=>`<button class="color-choice" data-color="${name}" aria-label="${name}" aria-pressed="${light.color===name}" style="--color:${color}"><i></i><span>${name}</span></button>`).join('')}</div></div></div>`;model.lights.forEach((_,i)=>paintLight(i));break;}
  case 'climate':title('');pane.innerHTML=`<div class="dial-layout"><button class="temp-side minus" data-action="temp-minus" aria-label="Lower target by one degree"></button><button class="temp-side plus" data-action="temp-plus" aria-label="Raise target by one degree"></button><div class="thermostat" role="slider" tabindex="0" aria-label="Target temperature" aria-valuemin="16" aria-valuemax="30" aria-valuenow="${model.target}" aria-valuetext="${model.target} degrees Celsius"><svg viewBox="0 0 320 320" aria-hidden="true"><g class="degree-guides">${Array.from({length:15},(_,i)=>{const v=16+i,a=(225-i/14*270)*Math.PI/180,major=v%5===0||i===0;const point=r=>[160+r*Math.cos(a),160-r*Math.sin(a)];const a1=point(134),a2=point(major?143:139);return `<line x1="${a1[0]}" y1="${a1[1]}" x2="${a2[0]}" y2="${a2[1]}" class="${major?'major':''}"/>`;}).join('')}</g><path class="dial-track" d="M 72.32 247.68 A 124 124 0 1 1 247.68 247.68"/><path class="dial-active" d="M 72.32 247.68 A 124 124 0 1 1 247.68 247.68" pathLength="100"/><text class="dial-limit" x="65" y="272">16</text><text class="dial-limit" x="255" y="272">30</text><g data-dial-pointer><circle class="dial-thumb" r="19"/><text class="target-label" data-target></text></g></svg><div class="dial-number"><strong data-current-temperature>${model.current??'—'}</strong><span class="temperature-unit"><span class="thermal-mode" data-thermal-mode></span><span>C</span></span></div></div>${sensorSelector()}</div>`;paintDial();break;
  case 'timer':{
    title('Timer');const remaining=model.timer?timerRemaining():model.timerDraft;pane.innerHTML=`<div class="center-task"><div class="timer-adjust"><button class="circle-button" data-action="timer-minus" aria-label="Subtract one minute">${icon('minus')}</button><div class="big-time" data-timer-big>${duration(remaining)}</div><button class="circle-button" data-action="timer-plus" aria-label="Add one minute">${icon('plus')}</button></div>${!model.timer?`<div class="preset-row">${[60,300,600,900].map(s=>`<button data-timer-preset="${s}" aria-pressed="${model.timerDraft===s}">${s/60} min</button>`).join('')}</div>`:'<p class="subtle">'+(model.timer.end?'Running':'Paused')+'</p>'}<div class="task-actions">${model.timer?`<button class="button-primary" data-action="timer-pause">${model.timer.end?'Pause':'Resume'}</button><button class="button-secondary" data-action="timer-cancel">Cancel</button>`:autoButton('Start timer','timer-save')}</div><p class="auto-caption" data-auto-caption>${model.timer?'':'5 minutes'}</p></div>`;break;}
  case 'new-reminder':title(model.editingReminder===null?'New reminder':'Reminder');pane.innerHTML=`<div class="center-task"><form class="reminder-form" data-form="reminder"><div class="field"><label for="reminder-v2">Remember to</label><input id="reminder-v2" name="text" data-input="reminder" maxlength="160" placeholder="Reminder" value="${esc(model.reminderDraft)}" autocomplete="off"></div><div class="deadline-line"><label for="deadline-v2">When</label><input type="datetime-local" id="deadline-v2" name="deadline" data-input="deadline" value="${model.reminderDeadline}" aria-label="Reminder deadline"></div><p class="subtle" style="margin-top:8px;font-size:11px">Optional</p><div class="task-actions">${autoButton('Save reminder','reminder-save')}</div><p class="auto-caption" data-auto-caption></p></form></div>`;break;
  case 'reminders':title('Reminders');pane.innerHTML=`<div class="reminders-layout"><div class="section-line"><span class="subtle">${model.reminders.filter(r=>!r.done).length} remaining · Swipe right to finish</span><button data-action="new-reminder" aria-label="Add reminder">${icon('plus')}</button></div>${model.reminders.map((r,i)=>r.done?'':reminderEntry(r,i)).join('')||'<p class="subtle">All done</p>'}</div>`;break;
  case 'contacts':title('Calls');pane.innerHTML=`<div class="contacts">${[['Mom','M','Audio'],['Alex','A','Audio'],['Front door','video','Camera']].map(([name,letter,label])=>`<button class="contact-button" data-contact="${name}"><span class="avatar">${letter==='video'?icon('video'):letter}</span><span>${name}</span><small>${label}</small></button>`).join('')}</div>`;break;
  case 'call':renderCall(pane);break;
  case 'music':title('');pane.innerHTML=`<div class="music-layout"><div class="record" aria-hidden="true">${icon('disc-3')}</div><div class="music-info"><h2>${tracks[model.song][0]}</h2><p class="subtle">${tracks[model.song][1]}</p><div class="music-buttons"><button data-action="shuffle" aria-label="Shuffle" aria-pressed="${model.shuffle}">${icon('shuffle')}</button><button data-action="previous" aria-label="Previous track">${icon('skip-back')}</button><button class="play-control" data-action="playpause" aria-label="${model.playing?'Pause':'Play'}">${icon(model.playing?'pause':'play')}</button><button data-action="next" aria-label="Next track">${icon('skip-forward')}</button><button data-action="repeat" aria-label="Repeat: ${model.repeat}" aria-pressed="${model.repeat!=='off'}">${icon(model.repeat==='track'?'repeat-1':'repeat')}</button></div><input class="seek-track" type="range" min="0" max="${tracks[model.song][2]}" value="${model.position}" data-input="seek" aria-label="Playback position"><div class="track-times"><span data-track-time>${duration(model.position)}</span><span>${duration(tracks[model.song][2])}</span></div><div class="music-volume"><button data-action="sound-mute" aria-label="Mute sounds">${icon('volume-2')}</button><input type="range" min="0" max="100" value="${model.volume}" data-input="volume" aria-label="Volume"><button data-action="stop-music" aria-label="Stop music">${icon('square')}</button></div></div></div>`;paintVolume();break;
  case 'weather':title('Manila · Demo weather');pane.innerHTML=`<div class="center-task"><div class="answer-weather">${icon('cloud-sun')}<strong>28°</strong></div><h2>Partly cloudy</h2><p class="subtle">High 30° · Low 25°</p></div>`;break;
  case 'intent':title('Request history');pane.innerHTML=`<div class="history-layout"><div class="history-list">${model.history.map((item,i)=>`<button data-history="${i}" aria-pressed="${model.historyIndex===i}"><strong>${esc(item.result.intent)}</strong><small>${new Date(item.timestamp).toLocaleTimeString()} · ${item.source==='onnx-simulated'?'ONNX fixture':'Touch'}</small></button>`).join('')||'<p class="subtle">No requests yet.</p>'}</div><div class="history-detail"><pre>${esc(JSON.stringify(model.history[model.historyIndex]??{input:'intent + parameters',asr:false,simulated:true},null,2))}</pre></div></div><p class="demo-note">Last 30 requests · Synthetic inference · No network calls</p>`;break;
  case 'demo':title('Simulator');pane.innerHTML=`<div class="demo-grid">${DEMO.map(([label,symbol,event],i)=>`<button data-demo="${i}">${icon(symbol)}${label}</button>`).join('')}</div><div class="sim-label">Aura states</div><div class="demo-state-row">${Object.keys(AURA_STATES).map(s=>`<button data-agent="${s}">${s}</button>`).join('')}</div><p class="demo-note">VCM intents only. Text is entered on screen. Every action is simulated.</p>`;break;
 }
}
function selectedTemperatureSensor(){return TEMPERATURE_SENSORS.find(sensor=>sensor.entity_id===model.temperatureSensor);}
function sensorSelector(){return `<div class="sensor-source"><label for="temperature-source">Display sensor</label><select id="temperature-source" data-input="temperature-sensor" aria-label="Home Assistant temperature sensor">${TEMPERATURE_SENSORS.map(sensor=>`<option value="${sensor.entity_id}" ${sensor.entity_id===model.temperatureSensor?'selected':''}>${esc(sensor.attributes.friendly_name)} · ${temperatureCelsius(sensor)===null?'Unavailable':temperatureCelsius(sensor)+'°C'}</option>`).join('')}</select><small data-sensor-entity>${esc(model.temperatureSensor)}</small></div>`;}
function selectTemperatureSensor(entityId){const sensor=TEMPERATURE_SENSORS.find(s=>s.entity_id===entityId);if(!sensor)return;model.temperatureSensor=entityId;model.current=temperatureCelsius(sensor);receipt('display.temperature_sensor',{entity_id:entityId});paintEnvironment();paintDial();setText('[data-sensor-entity]',entityId);model.lastInteraction=Date.now();}
function paintEnvironment(){setText('[data-home-temperature]',model.current??'—');q('.home-temperature').setAttribute('aria-label',`${selectedTemperatureSensor().attributes.friendly_name}: ${model.current===null?'unavailable':model.current+' degrees Celsius'}`);}
function paintDial(){const dial=q('.thermostat');if(!dial)return;const valid=model.current!==null,f=(model.target-16)/14,actual=valid?(model.current-16)/14:0,angle=(225-f*270)*Math.PI/180;const delta=valid?model.current-model.target:0;const mode=!valid?'unavailable':delta>.5?'cooling':delta<-.5?'heating':'holding';dial.dataset.thermal=mode;dial.style.setProperty('--dial-offset',String(100*(1-Math.max(0,Math.min(1,actual)))));q('[data-dial-pointer]').setAttribute('transform',`translate(${160+124*Math.cos(angle)} ${160-124*Math.sin(angle)})`);dial.setAttribute('aria-valuenow',String(model.target));dial.setAttribute('aria-valuetext',`Target ${model.target} degrees Celsius; ${valid?'current '+model.current+'; '+mode:'current reading unavailable'}`);setText('[data-current-temperature]',model.current??'—');setText('[data-target]',model.target+'°');q('[data-thermal-mode]').innerHTML=icon(mode==='cooling'?'snowflake':mode==='heating'?'flame':'minus');}
function adjustTemperature(value){model.target=Math.round(Math.max(16,Math.min(30,value)));paintDial();receipt('climate.set_temperature',{entity_id:'climate.living_room',temperature:model.target});}
function dialAt(event){const r=q('.thermostat').getBoundingClientRect();const dx=event.clientX-(r.left+r.width/2),dy=event.clientY-(r.top+r.height/2);if(Math.hypot(dx,dy)<r.width*.29)return;let deg=Math.atan2(dy,dx)*180/Math.PI;let progress=(deg+225)%360;if(progress<0)progress+=360;if(progress>270)progress=progress>315?0:270;adjustTemperature(16+progress/270*14);}
function timerRemaining(){return !model.timer?0:model.timer.end?Math.max(0,(model.timer.end-Date.now())/1000):model.timer.remaining;}
function saveTimer(){stopAuto();model.timer={total:model.timerDraft,remaining:model.timerDraft,end:Date.now()+model.timerDraft*1000};receipt('timer.set',{seconds:model.timerDraft});restoreHome();toast('timer','Timer started',duration(model.timerDraft),'timer');setAgent('speaking',{settle:true});}
function saveAlarm(){if(!/^\d{2}:\d{2}$/.test(model.alarmDraft))return;stopAuto();model.alarm={time:model.alarmDraft,deadline:nextAlarm(model.alarmDraft,Date.now())};receipt('alarm.set',{time:model.alarm.time});restoreHome();toast('alarm-clock',clockTime(model.alarm.deadline),'In '+until(model.alarm.deadline),'alarm');setAgent('speaking',{settle:true});}
function saveReminder(){const parsed=model.reminderDeadline?new Date(model.reminderDeadline).getTime():null;if(parsed!==null&&!Number.isFinite(parsed))return;stopAuto();const text=model.reminderDraft.trim()||'Reminder';const r={id:Date.now(),text,deadline:parsed,done:false,unread:true,nearShown:false,dueShown:false,visibleUntil:Date.now()+30000};if(model.editingReminder===null)model.reminders.push({...r,pinned:false});else{const previous=model.reminders[model.editingReminder];model.reminders[model.editingReminder]={...previous,...r,id:previous.id};}model.remindersExpanded=true;model.remindersEditUntil=Date.now()+30000;model.editingReminder=null;receipt('reminder.add',{text,deadline:parsed?new Date(parsed).toISOString():null});renderReminderCount();restoreHome();toast('check','Reminder saved',text,'reminders');setAgent('speaking',{settle:true});}
function renderRail(){const structure=Boolean(model.timer)+'/'+Boolean(model.alarm);if(structure!==lastRail){q('.time-rail').innerHTML=(model.timer?`<button class="time-chip" data-open="timer"><span class="rotating-hourglass">${icon('hourglass')}</span><span><strong data-rail-timer></strong><small data-timer-status></small></span></button>`:'')+(model.alarm?`<button class="time-chip" data-open="alarm">${icon('alarm-clock')}<span><strong data-rail-alarm></strong><small data-alarm-relative></small></span></button>`:'');lastRail=structure;}if(model.timer){setText('[data-rail-timer]',duration(timerRemaining()));setText('[data-timer-status]',model.timer.end?'Timer':'Paused');q('.rotating-hourglass').classList.toggle('paused',!model.timer.end);q('.time-chip[data-open=timer]').setAttribute('aria-label','Timer '+duration(timerRemaining()));}if(model.alarm){setText('[data-rail-alarm]',clockTime(model.alarm.deadline));setText('[data-alarm-relative]','In '+until(model.alarm.deadline));}}
function alertNotification(alert){if(model.alert){model.alertQueue.push(alert);return;}model.alert={...alert,closesAt:Date.now()+300000};stopAuto();closeToast();q('.home-layer').inert=true;q('.task-view').inert=true;q('.alert-surface').hidden=false;const edge=q('.attention-edge');edge.hidden=false;edge.style.animation='none';void edge.offsetWidth;edge.style.animation='';q('.alert-content').innerHTML=(alert.kind==='reminder'?'':icon(alert.kind==='timer'?'timer':'alarm-clock'))+`<h2>${esc(alert.title)}</h2><p class="subtle">${esc(alert.subtitle)}</p><div class="task-actions"><button class="button-secondary" data-action="alert-snooze">${alert.kind==='reminder'?'In 5 min':'Snooze 5 min'}</button><button class="button-primary" data-action="alert-dismiss">${alert.kind==='reminder'?'Got it':'Dismiss'}</button></div>`;q('[data-action=alert-dismiss]').focus({preventScroll:true});setText('[data-announcement]',alert.title);setAgent('idle');}
function dismissAlert(snooze){const a=model.alert;if(snooze){if(a.kind==='reminder'&&a.reminder){model.alertQueue=model.alertQueue.filter(queued=>queued.reminder?.id!==a.reminder.id);a.reminder.deadline=Date.now()+300000;a.reminder.nearShown=false;a.reminder.dueShown=false;}else if(a.kind==='timer')model.timer={total:300,remaining:300,end:Date.now()+300000};else if(a.kind==='alarm')model.alarm={time:(()=>{const d=new Date(Date.now()+300000);return String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');})(),deadline:Date.now()+300000};}if(a.reminder)a.reminder.unread=false;model.alert=null;q('.alert-surface').hidden=true;q('.attention-edge').hidden=true;q('.task-view').inert=false;q('.home-layer').inert=model.view!=='home';renderReminderCount();if(model.alertQueue.length)alertNotification(model.alertQueue.shift());else if(model.view!=='home'){renderView();q('.close-task').focus({preventScroll:true});}else q('.wake-target').focus({preventScroll:true});renderRail();}
function startCall(name){if(model.call){open('call');return;}model.call={name,started:Date.now(),muted:false,speaker:true};model.cameraExpanded=false;model.cameraEnabled=true;receipt('call.start',{contact:name,simulated:true});open('call');updateCallPeek();}
function updateCallPeek(){q('.call-peek').hidden=!model.call;if(model.call){const avatar=q('[data-call-avatar]');if(avatar.dataset.person!==model.call.name){avatar.dataset.person=model.call.name;avatar.innerHTML=model.call.name==='Front door'?icon('video'):esc(model.call.name[0]);}setText('[data-call-elapsed]',duration((Date.now()-model.call.started)/1000));}}
function callControls(){return `<div class="call-controls"><button data-action="call-mute" aria-label="Mute call" aria-pressed="${model.call.muted}">${icon(model.call.muted?'mic-off':'mic')}</button><button data-action="call-camera" aria-label="${model.cameraEnabled?'Disable':'Enable'} camera" aria-pressed="${model.cameraEnabled}">${icon(model.cameraEnabled?'video':'video-off')}</button><button data-action="call-speaker" aria-label="Speaker" aria-pressed="${model.call.speaker}">${icon('volume-2')}</button><button class="hangup" data-action="hangup" aria-label="End call">${icon('phone-off')}</button></div>`;}
function renderCall(pane){if(!model.call){open('contacts');return;}title(model.cameraExpanded?'Front door':'Call');pane.innerHTML=model.cameraExpanded?`<div class="video-expanded"><canvas class="camera-canvas" width="640" height="360" aria-label="Simulated camera test feed"></canvas><span class="camera-caption">Front door · Simulated feed</span><button class="close-task" data-action="camera-collapse" aria-label="Collapse camera">${icon('minimize-2')}</button>${callControls()}</div>`:`<div class="center-task call-person"><div class="avatar">${model.call.name==='Front door'?icon('video'):esc(model.call.name[0])}</div><h2>${esc(model.call.name)}</h2><div class="call-duration" data-call-duration>${duration((Date.now()-model.call.started)/1000)}</div>${callControls()}</div>${model.cameraEnabled?'<button class="camera-preview" data-action="camera-expand" aria-label="Expand simulated camera feed"><canvas class="camera-canvas" width="320" height="180"></canvas><span class="camera-caption">Front door · Demo</span></button>':''}`;drawCamera();}
function drawCamera(){const canvas=q('.camera-canvas');if(!canvas)return;const c=canvas.getContext('2d'),w=canvas.width,h=canvas.height,t=Date.now()/1000;c.fillStyle='#18282e';c.fillRect(0,0,w,h);const grad=c.createLinearGradient(0,0,w,h);grad.addColorStop(0,'#37535c');grad.addColorStop(1,'#101a20');c.fillStyle=grad;c.fillRect(0,0,w,h);c.strokeStyle='#aac9ce14';c.lineWidth=1;for(let x=0;x<w;x+=w/12){c.beginPath();c.moveTo(x,0);c.lineTo(x,h);c.stroke();}for(let y=0;y<h;y+=h/7){c.beginPath();c.moveTo(0,y);c.lineTo(w,y);c.stroke();}c.strokeStyle='#b8d5d75c';c.strokeRect(w*.18,h*.14,w*.64,h*.72);c.beginPath();c.moveTo(w*.43,h*.5);c.lineTo(w*.57,h*.5);c.moveTo(w*.5,h*.43);c.lineTo(w*.5,h*.57);c.stroke();c.fillStyle='#d9edeb14';c.fillRect((t*30)%(w+50)-50,0,35,h);c.fillStyle='#c3d8db';c.font=`${w/28}px monospace`;c.fillText(model.cameraEnabled?'CAM 01  /  DEMO':'CAMERA OFF',w*.05,h*.10);c.font=`${w/36}px monospace`;c.fillText(new Date().toLocaleTimeString(),w*.62,h*.94);}

// The VCM supplies structured intent slots. No natural-language parsing or ASR exists here.
const DEMO=[
 ['Lights · 40%','lightbulb',{intent:'light.brightness',parameters:{entity_id:'light.living_room',brightness_pct:40}}],
 ['Light tray','layout-grid',{intent:'light.list',parameters:{}}],['Temperature','thermometer',{intent:'climate.set_temperature',parameters:{entity_id:'climate.living_room',temperature:24}}],
 ['Timer · 5 min','timer',{intent:'timer.set',parameters:{seconds:300}}],['Alarm · 7 am','alarm-clock',{intent:'alarm.set',parameters:{time:'07:00'}}],
 ['New reminder','plus',{intent:'reminder.create',parameters:{}}],['Play music','music-2',{intent:'media.play',parameters:{id:0}}],
 ['Weather','cloud-sun',{intent:'answer.weather',parameters:{location:'Manila'}}],['Call Mom','phone',{intent:'call.start',parameters:{contact:'Mom'}}],
 ['Camera call','video',{intent:'call.start',parameters:{contact:'Front door'}}],['Reminder due','bell',{intent:'demo.reminder_due',parameters:{}}],
 ['Timer done','hourglass',{intent:'demo.timer_due',parameters:{}}],['Alarm rings','alarm-clock',{intent:'demo.alarm_due',parameters:{}}],
 ['Near deadline','clock-3',{intent:'demo.reminder_near',parameters:{}}],['Unknown light','circle-help',{intent:'light.brightness',parameters:{entity_id:'light.unknown',brightness_pct:50}}]
];
function dispatch(event){if(!event||typeof event.intent!=='string'||(event.parameters!==undefined&&(!event.parameters||typeof event.parameters!=='object'||Array.isArray(event.parameters)))){setAgent('failed');toast('circle-help','Incomplete intent','Choose a demo intent','demo');return;}const request=++model.request;restoreHome();setAgent('thinking');setTimeout(()=>{if(request!==model.request)return;const raw=event.parameters||{};const p={...raw};if(p.entity_id!==undefined)p.entityId=p.entity_id;if(p.brightness_pct!==undefined)p.brightness=p.brightness_pct;if(p.temperature!==undefined)p.target=p.temperature;
  if(event.intent==='light.brightness'&&(!model.lights.some(l=>l.id===p.entityId)||!Number.isFinite(p.brightness)||p.brightness<0||p.brightness>100)){receipt('needs_input',{reason:'Choose a known light and 0–100% brightness'});setAgent('failed');toast('circle-help','Which light?','Choose from your lights','lights');return;}
  receipt(event.intent,raw,'onnx-simulated');
  switch(event.intent){
   case 'light.brightness':{const l=model.lights.find(l=>l.id===p.entityId);l.brightness=p.brightness;l.on=p.brightness>0;model.selectedLight=model.lights.indexOf(l);toast('lightbulb',l.name,`${l.brightness}% · ${l.color}`,'lights');const glyph=q('.toast-main>svg');glyph.style.color=colors[l.color];glyph.style.filter=`drop-shadow(0 0 ${l.brightness/8}px ${colors[l.color]})`;break;}
   case 'light.on':case 'light.off':case 'light.toggle':{const l=model.lights.find(l=>l.id===p.entityId);if(!l){setAgent('failed');toast('circle-help','Which light?','Choose from your lights','lights');return;}l.on=event.intent==='light.toggle'?!l.on:event.intent==='light.on';if(l.on&&!l.brightness)l.brightness=l.lastBrightness||50;model.selectedLight=model.lights.indexOf(l);toast('lightbulb',l.name,l.on?l.brightness+'% · '+l.color:'Off','lights');break;}
   case 'light.color':{const l=model.lights.find(l=>l.id===p.entityId);const chosen=p.color??Object.keys(LIGHT_COLORS).find(name=>p.rgb_color?JSON.stringify(LIGHT_COLORS[name].rgb_color)===JSON.stringify(p.rgb_color):LIGHT_COLORS[name].color_temp_kelvin===p.color_temp_kelvin);if(!l||!supportsColor(l,chosen)){setAgent('failed');toast('circle-help','Color unavailable','Choose a supported light color','lights');return;}l.color=chosen;l.on=true;if(!l.brightness)l.brightness=l.lastBrightness||50;model.selectedLight=model.lights.indexOf(l);toast('lightbulb',l.name,l.brightness+'% · '+l.color,'lights');break;}
   case 'light.list':open('lights');break;
   case 'climate.set_temperature':if(!Number.isFinite(p.target)||p.target<16||p.target>30){setAgent('failed');toast('thermometer','16–30°C','Choose a target','climate');return;}model.target=p.target;toast('thermometer',p.target+'° target',model.current===null?'Sensor unavailable':'Inside '+model.current+'°','climate');break;
   case 'timer.set':if(!Number.isFinite(p.seconds)||p.seconds<1||p.seconds>86400){setAgent('failed');return;}model.timerDraft=p.seconds;model.timer={total:p.seconds,remaining:p.seconds,end:Date.now()+p.seconds*1000};toast('hourglass','Timer started',duration(p.seconds),'timer');break;
   case 'alarm.set':if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(p.time)){setAgent('failed');return;}model.alarmDraft=p.time;model.alarm={time:p.time,deadline:nextAlarm(p.time,Date.now())};toast('alarm-clock',clockTime(model.alarm.deadline),'In '+until(model.alarm.deadline),'alarm');break;
   case 'reminder.create':model.editingReminder=null;open('new-reminder',{automatic:true});break;
   case 'media.play':model.song=0;model.playing=true;model.mediaLoaded=true;model.position=0;paintMusicPeek();toast('music-2',tracks[0][0],tracks[0][1],'music');break;
   case 'answer.weather':open('weather');model.weatherCloseAt=null;break;
   case 'call.start':if(!['Mom','Alex','Front door'].includes(p.contact)){setAgent('failed');return;}startCall(p.contact);break;
   case 'demo.reminder_due':case 'demo.reminder_near':{const r={id:Date.now(),text:'Check the oven',deadline:Date.now()+(event.intent.endsWith('near')?45000:0),done:false,unread:true,nearShown:false,dueShown:false};model.reminders.push(r);renderReminderCount();checkDeadlines();return;}
   case 'demo.timer_due':model.timer={total:1,remaining:0,end:Date.now()};checkDeadlines();return;
   case 'demo.alarm_due':model.alarm={time:'Demo',deadline:Date.now()};checkDeadlines();return;
   default:setAgent('failed');toast('circle-help','Not available','Try a demo intent','demo');return;
  }setAgent('speaking',{settle:true});renderRail();
 },380);}
function checkDeadlines(){const now=Date.now();if(model.timer?.end&&model.timer.end<=now){model.timer=null;alertNotification({kind:'timer',title:'Timer finished',subtitle:'Time’s up.'});}if(model.alarm&&model.alarm.deadline<=now){const a=model.alarm;model.alarm=null;alertNotification({kind:'alarm',title:clockTime(a.deadline),subtitle:'Alarm'});}for(const r of model.reminders){if(r.done||!r.deadline)continue;if(r.deadline<=now&&!r.dueShown){r.dueShown=true;r.nearShown=true;r.unread=true;alertNotification({kind:'reminder',title:r.text,subtitle:'Due now',reminder:r});}else if(r.deadline>now&&r.deadline-now<=60000&&!r.nearShown){r.nearShown=true;r.unread=true;alertNotification({kind:'reminder',title:r.text,subtitle:'In less than a minute',reminder:r});}}renderReminderCount();}

// Reordering is deliberately owned only by the grip, never by a row or its text.
function reorderReminder(from,to){if(from===to)return;const [r]=model.reminders.splice(from,1);model.reminders.splice(to,0,r);receipt('reminder.reorder',{ids:model.reminders.filter(r=>!r.done).map(r=>r.id)});refreshReminderSurfaces();}
root.addEventListener('pointerdown',event=>{const grip=event.target.closest('[data-reorder-reminder]');if(!grip)return;event.preventDefault();grip.setPointerCapture(event.pointerId);const row=grip.closest('[data-reminder-swipe]');reminderOrderDrag={pointer:event.pointerId,index:Number(grip.dataset.reorderReminder),target:Number(grip.dataset.reorderReminder),grip,row,y:event.clientY,moved:false};});
