function paintMusicPeek(){q('.music-peek').hidden=!model.mediaLoaded;const play=q('.peek-play');const label=model.playing?'Pause music':'Play music';if(play.getAttribute('aria-label')!==label){play.innerHTML=icon(model.playing?'pause':'play');play.setAttribute('aria-label',label);}if(!model.mediaLoaded)return;setText('[data-peek-song]',tracks[model.song][0]);setText('[data-peek-artist]',tracks[model.song][1]);q('.music-peek').style.setProperty('--track-progress',String(model.position/tracks[model.song][2]));q('.music-peek').classList.toggle('paused',!model.playing);setText('[data-track-time]',duration(model.position));const seek=q('[data-input=seek]');if(seek&&document.activeElement!==seek)seek.value=String(model.position);}
